151	/** Contexto runtime do painel (lojas + canais) — reusado pelo drill-down. */
152	export interface TvContext {
153	  lojas: TvLoja[];
154	  /** Lojas com venda live (existem em `degust_stores`). */
155	  degustLojaIds: Set<number>;
156	  /** Mapa código Degust → loja_id (corrige pass-through da edge function). */
157	  degustCodeToLoja: Map<number, number>;
158	  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
159	  linxLojaIds: number[];
160	  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
161	  factoryLojaId: number | null;
162	}
163	
164	function isFactoryTipo(tipo: string | null): boolean {
165	  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
166	  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
167	}
168	
169	/** Carrega o contexto (exportado para o `useTvStoreDetail` compartilhar cache). */
170	export async function fetchTvContext(): Promise<TvContext> {
171	  const [lojasRes, degustRes] = await Promise.all([
172	    supabase
173	      .from('lojas')
174	      .select('id, nome, tipo')
175	      .eq('ativo', true)
176	      .order('id'),
177	    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
178	  ]);
179	  if (lojasRes.error) throw lojasRes.error;
180	  if (degustRes.error) throw degustRes.error;
181	
182	  const lojas: TvLoja[] = lojasRes.data ?? [];
183	  const degustLojaIds = new Set<number>();
184	  const degustCodeToLoja = new Map<number, number>();
185	  for (const row of degustRes.data ?? []) {
186	    degustLojaIds.add(row.loja_id);
187	    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
188	  }
189	
190	  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
191	  const linxLojaIds = lojas
192	    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
193	    .map((l) => l.id);
194	
195	  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
196	}
