386	
387	/** Exportado para o `useTvStoreDetail` compartilhar a MESMA query/cache. */
388	export async function fetchStockAlerts(): Promise<StockRow[]> {
389	  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
390	  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas
391	  // candidatas hoje). Paginação obrigatória: o PostgREST corta em 1000 linhas
392	  // mesmo com `.limit()` maior — `.order('id')` garante páginas estáveis.
393	  //
394	  // `setor` vai junto no select: a regra do CTO 2026-06-05 (alertas SÓ do
395	  // setor TV_ALERT_SETOR = produtos vendáveis) é aplicada client-side com
396	  // normalização em `buildStockSummary` — a caixa/acento no banco é
397	  // inconsistente ("CÂMARA FRIA" vs "Câmara Fria"), então um `.eq` server-side
398	  // exato deixaria variantes legítimas de "Produtos" passarem/caírem errado.
399	  const data = await fetchAllPages((from, to) =>
400	    supabase
401	      .from('estoque')
402	      .select(
403	        'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo, setor)',
404	      )
405	      .eq('produto_master.ativo', true)
406	      .gt('quantidade_minima', 0)
407	      .or('oculto.is.null,oculto.eq.false')
408	      .order('id')
409	      .range(from, to),
410	  );
411	  return data.map((row) => ({
412	    loja_id: row.loja_id,
413	    quantidade_atual: row.quantidade_atual,
414	    quantidade_minima: row.quantidade_minima,
415	    produtoNome: row.produto_master?.nome ?? '(sem nome)',
416	    setor: row.produto_master?.setor ?? null,
417	  }));
418	}
