424	async function fetchMovementsToday(): Promise<Map<number, MovementAggregate>> {
425	  const startOfDay = new Date();
426	  startOfDay.setHours(0, 0, 0, 0);
427	  // Pico real >1k movimentações/dia: paginar (PostgREST corta em 1000).
428	  const data = await fetchAllPages((from, to) =>
429	    supabase
430	      .from('movimentacoes')
431	      .select('loja_id, tipo_movimentacao, data_movimentacao')
432	      .gte('data_movimentacao', startOfDay.toISOString())
433	      .order('id')
434	      .range(from, to),
435	  );
436	  return aggregateMovements(data);
437	}
