489	// Perdas no período do filtro global (tabela `perdas`)
490	// ─────────────────────────────────────────────────────────────────────────────
491	
492	/** Par período corrente + período anterior equivalente (comparativo). */
493	export interface PeriodedAggregates<T> {
494	  current: T;
495	  previous: T;
496	}
497	
498	async function loadPerdasRange(range: TvDateRange): Promise<PerdasByLoja> {
499	  const bounds = rangeToLocalDayBounds(range);
500	  // Paginado: um mês de perdas pode passar de 1000 linhas (corte silencioso
501	  // do PostgREST). `data_identificacao` é timestamptz → bounds de dia local.
502	  const rows = await fetchAllPages((from, to) =>
503	    supabase
504	      .from('perdas')
505	      .select('loja_id, valor_estimado')
506	      .gte('data_identificacao', bounds.startIso)
507	      .lt('data_identificacao', bounds.endExclusiveIso)
508	      .order('id')
509	      .range(from, to),
510	  );
511	  return aggregatePerdas(rows);
512	}
513	
514	async function fetchPerdasAggregates(
515	  period: TvPeriod,
516	): Promise<PeriodedAggregates<PerdasByLoja>> {
517	  const now = new Date();
518	  const [current, previous] = await Promise.all([
519	    loadPerdasRange(periodRange(period, now)),
520	    loadPerdasRange(previousPeriodRange(period, now)),
521	  ]);
522	  return { current, previous };
523	}
