606	/** Retorno do {@link useTvDashboardData}. */
607	export interface TvDashboardData {
608	  network: TvNetworkSummary | null;
609	  stores: TvStoreData[];
610	  factory: TvFactoryData | null;
611	  exceptions: TvExceptionsResult;
612	  freshness: TvFreshness;
613	  /** Período do filtro global aplicado a perdas/compras/comparativos. */
614	  period: TvPeriod;
615	  /** Range corrente do filtro (para rótulos na UI). */
616	  range: TvDateRange;
617	  /** Range anterior equivalente usado nos comparativos. */
618	  previousRange: TvDateRange;
619	  /** true enquanto o contexto (lojas/canais) ainda não carregou. */
620	  isLoading: boolean;
621	  /** true quando o contexto falhou (painel não consegue montar). */
622	  isError: boolean;
623	}
624	
625	const EMPTY_MOVEMENT: TvMovementSummary = {
626	  entradas: 0,
627	  saidas: 0,
628	  ultimaBipagem: null,
629	};
630	
631	const EMPTY_PERDAS_AGG: PerdasAggregate = { valor: 0, itens: 0 };
632	
633	/** Monta o resumo de perdas de UMA unidade a partir dos agregados. */
634	function perdasSummaryFor(
635	  agg: PeriodedAggregates<PerdasByLoja> | undefined,
636	  lojaId: number,
637	): TvPerdasSummary {
638	  const cur = agg?.current.byLoja.get(lojaId) ?? EMPTY_PERDAS_AGG;
639	  const prev = agg?.previous.byLoja.get(lojaId);
640	  return {
641	    valor: cur.valor,
642	    itens: cur.itens,
643	    deltaPct: relativeDelta(cur.valor, prev?.valor ?? null),
644	  };
645	}
646	
647	/** Monta o resumo de compras de UMA unidade a partir dos agregados. */
648	function comprasSummaryFor(
649	  agg: PeriodedAggregates<ComprasByLoja> | undefined,
650	  lojaId: number,
651	): TvComprasSummary {
652	  const cur = agg?.current.byLoja.get(lojaId) ?? 0;
653	  const prev = agg?.previous.byLoja.get(lojaId);
654	  return { valor: cur, deltaPct: relativeDelta(cur, prev ?? null) };
655	}
